// Every number on screen comes from estudio/dados/fechamento.json, generated by
// estudio/scripts/extrair_dados.py from the engine output. The JSON is imported straight
// from its place in the studio (no copy that could go stale). This module only joins
// numbers to the approved screen text of STORYBOARD.md; it never types a number.

import raw from '../../dados/fechamento.json';
import {parseRawDecimal} from './format';

export const data = raw;

const fail = (message: string): never => {
  throw new Error(`fechamento.json: ${message}`);
};

// Scene 1 and 2: the seven files, in the storyboard order, with the approved labels
// (corte r1: label only, no volume).
export type FileKind = 'report' | 'adjustments' | 'rates' | 'email' | 'chart' | 'statement';
const FILE_LABELS: {prefix: string; label: string; kind: FileKind}[] = [
  {prefix: '01_', label: 'Relatório da Orbe', kind: 'report'},
  {prefix: '06_', label: 'Ajustes da Orbe', kind: 'adjustments'},
  {prefix: '02_', label: 'Taxas contratadas', kind: 'rates'},
  {prefix: '03_', label: 'E-mail da Ponte', kind: 'email'},
  {prefix: '04_', label: 'Plano de contas', kind: 'chart'},
  {prefix: '05a_', label: 'Extrato Aurora', kind: 'statement'},
  {prefix: '05b_', label: 'Extrato Meridiano', kind: 'statement'},
];

export const files = FILE_LABELS.map((f) => {
  const source = data.arquivos.find((a) => a.arquivo.startsWith(f.prefix)) ?? fail(`missing file ${f.prefix}`);
  return {label: f.label, kind: f.kind, lines: source.linhas};
});

// Scene 2.
export const financeRules = data.regras_do_financeiro.valor;

// Scene 3: four lanes by stage (corte r2), totals from eventos.por_etapa. The engine's
// PENDENCIAS front is only emission order; por_etapa counts those events in the stage of
// their source file, as the panel does.
const LANES: {key: keyof typeof raw.eventos.por_etapa; label: string}[] = [
  {key: 'CHECKOUT', label: 'Checkout'},
  {key: 'REMESSA', label: 'Remessa'},
  {key: 'NOTAS', label: 'Notas'},
  {key: 'EXTRATOS', label: 'Extratos'},
];
export const lanes = LANES.map((l) => ({label: l.label, total: data.eventos.por_etapa[l.key]}));
export const decisions = data.eventos.decisoes;
export const byWeight = data.eventos.por_peso;
export const runSeconds = data.duracao_s.valor;

// The running sum of the lanes must end on the decision total, or the counter would lie.
const laneSum = lanes.reduce((s, l) => s + l.total, 0);
if (laneSum !== decisions) fail(`lanes sum ${laneSum} differs from eventos.decisoes ${decisions}`);
const weightSum = byWeight.rotina + byWeight.atencao + byWeight.excecao;
if (weightSum !== decisions) fail(`por_peso sum ${weightSum} differs from eventos.decisoes ${decisions}`);

// Scene 4: one number, back to its origin line.
export const trace = data.rastro_um_numero;
export const ratePoints = trace.taxa_aplicada_pct - trace.taxa_contratada_pct;
// 83 sales and 4 refunds with the wrong rate: "operações", never "vendas".
export const flaggedOperations = trace.operacoes_com_divergencia;
export const originFields = trace.linha_origem_texto.split(';');
const findField = (match: (f: string) => boolean, what: string) => {
  const i = originFields.findIndex(match);
  return i >= 0 ? i : fail(`origin line has no field for ${what}`);
};
const plain = (t: string) => t.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const near = (a: number | null, b: number, tolerance: number) => a !== null && Math.abs(a - b) <= tolerance;
export const originDateIndex = findField((f) => f === trace.data_venda, 'data_venda');
// The raw file writes the merchant in capitals without accents nor "Ltda".
export const originMerchantIndex = findField((f) => f !== '' && plain(trace.lojista).startsWith(plain(f)), 'lojista');
export const originGrossIndex = findField((f) => parseRawDecimal(f) === trace.valor_bruto, 'valor_bruto');
export const originRateIndex = findField((f) => parseRawDecimal(f) === trace.taxa_aplicada_pct, 'taxa_aplicada_pct');
// Fee = gross x applied rate, to the cent (the file truncates: 6449,10 x 4,09% = 263,768 -> 263,76).
export const originFeeIndex = findField(
  (f) => near(parseRawDecimal(f), (trace.valor_bruto * trace.taxa_aplicada_pct) / 100, 0.01),
  'valor_taxa',
);
// Corte r2: one row with these five fields, in file order, and a narrow "…" cell in every
// gap of omitted fields (before, between and after).
export const ORIGIN_ELLIPSIS = '\u2026';
type OriginCell = {text: string; mark?: 'value' | 'exception'; ellipsis?: boolean};
const shownFields = [originDateIndex, originMerchantIndex, originGrossIndex, originRateIndex, originFeeIndex].sort((a, b) => a - b);
export const originCells: OriginCell[] = shownFields.flatMap((i, k) => {
  const previous = k === 0 ? -1 : shownFields[k - 1];
  const gap: OriginCell[] = i - previous > 1 ? [{text: ORIGIN_ELLIPSIS, ellipsis: true}] : [];
  const cell: OriginCell = {
    text: originFields[i],
    mark: i === originGrossIndex ? 'value' : i === originRateIndex ? 'exception' : undefined,
  };
  const tail: OriginCell[] = k === shownFields.length - 1 && i < originFields.length - 1 ? [{text: ORIGIN_ELLIPSIS, ellipsis: true}] : [];
  return [...gap, cell, ...tail];
});
export const originLine = trace.fontes.linha_origem.linha;

// Scene 5: money that showed up, never summed.
export const money = data.dinheiro_em_jogo;

// Scene 6: pendencies by owner and four approved examples (ids only locate the item).
export const pendingCount = data.pendencias.quantidade;
export const owners = Object.entries(data.pendencias.por_dono).map(([owner, n]) => ({owner, count: n}));
const ownerSum = owners.reduce((s, o) => s + o.count, 0);
if (ownerSum !== pendingCount) fail(`por_dono sum ${ownerSum} differs from pendencias.quantidade`);

const EXAMPLES: {id: string; text: string}[] = [
  {id: 'PEN-0001', text: 'Cobrar da Orbe · Rota Global'},
  {id: 'PEN-0003', text: 'Devolver à Casa do Estudante'},
  {id: 'PEN-0013', text: 'Pix recebido sem identificação'},
];
export const pendingExamples = EXAMPLES.map((e) => {
  const item = data.pendencias.itens.find((p) => p.id === e.id) ?? fail(`missing ${e.id}`);
  // Values are shown in absolute value (the storyboard asked it for transfers).
  return {text: e.text, value: Math.abs(item.valor_brl), owner: item.quem_decide};
});
